                &lt;a href=&quot;{% url &quot;catalog:item_list&quot; %}&quot;&gt;All&lt;/a&gt;
            &lt;/li&gt;
        {% for c in categories %}
            &lt;li {% if category.slug == c.slug %}class=&quot;selected&quot;{% endif %}&gt;
