<pre class="lang-cpp prettyprint-override"><code>namespace my_Namespace{
    class MyFirstClass{
       class NestedClass{
          public:
            NestedClass(int arg){};
            NestedClass(double arg{};
            NestedClass(std::string arg){};
       };
    };
};
