JavaScript issue with global variable assignment<p>I'm trying to create a weather widget using below code snippets. However, the global variables longitude and latitude values are not getting updated in the success function. I have tried all the combinations of globalThis and window objects but yet not been able to resolve the issue.</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>setInterval(showWeather, 900000);
setTimeout(showWeather,1000)

function showWeather(){
    var appid = "API_KEY_FOR_OPENWEATHERMAP";
    var latitude = 0;
    var longitude = 0;

    function success(position){
        window.latitude = position.coords.latitude;
        window.longitude = position.coords.longitude;
    }

    function error(){
        console.log('Some error occurred while retrieving your device location! Hence showing the default location weather!')
    }

    if(navigator.geolocation){
        navigator.geolocation.getCurrentPosition(success, error);
    }else{
        console.log("Your device doesn't support geolcation tracking! Hence showing the default location weather!")
    }

    async function fetchWeather(){
        var url = `https://api.openweathermap.org/data/2.5/weather?lat=${window.latitude}&amp;lon=${window.longitude}&amp;appid=${appid}&amp;units=metric`
        const response = await fetch(url);
        data = response.json();
        return data
    }

    fetchWeather().then(response=&gt;{
        const icon = response.weather[0].icon;
        document.getElementById("city").innerHTML = response.name;
        document.getElementById("temp").innerHTML = response.main.temp + "&amp;deg;";
        url = `https://openweathermap.org/img/w/${icon}.png`;
        document.getElementById("wicon").src = url;
    })
}</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;h5 id="city"&gt;User Location&lt;/h5&gt;
&lt;div&gt;
  &lt;img id="wicon" src="https://openweathermap.org/img/w/01d.png" alt="Weather icon"&gt;
  &lt;strong id="temp"&gt;Temperature&amp;deg;&lt;/strong&gt;
&lt;/div&gt;</code></pre>
</div>
</div>
</p>,"<p><code>getCurrentPosition()</code> is asynchronous, but you're not waiting for it to finish before using the results. You should call <code>fetchWeather()</code> from the <code>success()</code> function, since that's called when <code>getCurrentPosition()</code> finishes.</p>

