<p>It works perfectly! why?</p>
<pre><code>import java.util.Scanner;

public class Ventas {

    public static void main(String[] args) {


        Scanner scan = new Scanner(System.in);

        double numero = 0;
        double grande = 0;
        double pequeno = 0;
        double suma = 0;
        double media = 0;
        String comprobacion = &quot;&quot;;
        int grandePos = 0;
        int pequenoPos = 0;
        String[] semana = {&quot;Martes&quot;, &quot;Miercoles&quot;, &quot;Jueves&quot;, &quot;Viernes&quot;, &quot;Sabado&quot;, &quot;Domingo&quot;};

        while(numero != -1) {
            double[] dias = new double[6];
            for (int i = 0; i &lt; dias.length; i++) {
                numero = scan.nextDouble(); // This is line 25!
                suma += numero;
                if(numero != -1) {
                    dias[i] = numero;
                    if(numero &gt; grande) {
                        grande = numero;
                        grandePos = i;
                    }else if(pequeno == 0 || numero &lt; pequeno) {
                        pequeno = numero;
                        pequenoPos = i;
                    }
                }else {
                    break;
                }
            }
            media = ((suma - dias[5]) / 5);
            if(media &lt; dias[5]) {
                comprobacion = &quot;NO&quot;;
            }else {
                comprobacion = &quot;SI&quot;;
            }
        }

        System.out.println(semana[grandePos] + &quot; &quot; + semana[pequenoPos] + &quot; &quot; + comprobacion);

        scan.close();
