<p><strong>History.js</strong></p>
<pre><code>import moment from &quot;moment&quot;;
import React, { useState } from &quot;react&quot;;
import Firebase from &quot;../../config/firebase&quot;;
import ProductsList from &quot;../../components/productsList/ProductsList&quot;;
import {
  FlatList,
  Text,
  View,
  Image,
  TouchableWithoutFeedback,
  TextInput,
  ActivityIndicator,
} from &quot;react-native&quot;;
import { Colors } from &quot;../../staticValues/Colors&quot;;
import { Devicewidth, productCardWidth } from &quot;../../staticValues/Dimensions&quot;;
import { useEffect } from &quot;react&quot;;
import { styles } from &quot;../../styles/authStyle&quot;;

import { FontAwesome5 } from &quot;@expo/vector-icons&quot;;
import { I18n } from &quot;../../helper/Multilanguage&quot;;

export default function HistoryList({ navigation }) {
  const [filtredList, setfiltredList] = useState([]);

  const [isFetching, setisFetching] = useState(false);
  const [allProduct, setallProduct] = useState([]);
  const [searchInput, setsearchInput] = useState(&quot;&quot;);

  const [visible, setVisible] = React.useState(true);

  function onRefresh() {
    getAllProdcuts();
  }

  function getAllProdcuts() {
    setisFetching(true);
    Firebase.firestore()
      .collection(&quot;Products&quot;)
      .get()
      .then((docRef) =&gt; {
        var list = [];
        docRef.forEach((elm) =&gt; {
          list.push(elm.data());
        });
        setfiltredList(list);
        setallProduct(list);
        setisFetching(false);
      })
      .catch((error) =&gt; {
        console.log({ error });
        setisFetching(false);
      });
  }

  useEffect(() =&gt; {
    getAllProdcuts();
    const willFocusSubscription = navigation.addListener(&quot;focus&quot;, () =&gt; {
      getAllProdcuts();
    });

    return willFocusSubscription;
  }, []);

  return (
    &lt;View
      style={{
        flex: 1,
      }}
    &gt;
      &lt;View
        style={{
          width: &quot;80%&quot;,
          backgroundColor: Colors.lightGray,
          borderRadius: 30,
          height: 45,
          marginBottom: 5,
          justifyContent: &quot;center&quot;,
          padding: 20,
          alignSelf: &quot;center&quot;,
          marginTop: 10,
        }}
      &gt;
        &lt;FontAwesome5
          name={&quot;search&quot;}
          size={26}
          color={&quot;black&quot;}
          style={styles.inputIcon}
        /&gt;
        &lt;TextInput
          style={styles.loginpass}
          placeholder={I18n.t(&quot;searchProduct&quot;)}
          placeholderTextColor=&quot;#fff&quot;
          onChangeText={(input) =&gt; {
            setsearchInput(input);
            // filter list
            const SearchResult = allProduct.filter((product) =&gt;
              product.title.toLowerCase().includes(input.toLocaleLowerCase())
            );
            setfiltredList(SearchResult);
          }}
        /&gt;
      &lt;/View&gt;

      &lt;View
        style={{
          alignItems: &quot;center&quot;,
          flex: 1,
        }}
      &gt;
        &lt;FlatList
          ListEmptyComponent={() =&gt; {
            return (
              &lt;View&gt;
                {!isFetching &amp;&amp; (
                  &lt;Text
                    style={{
                      textAlign: &quot;center&quot;,
                      color: Colors.accentColor,
                      fontWeight: &quot;bold&quot;,
                      paddingVertical: 20,
                    }}
                  &gt;
                    {I18n.t(&quot;noProduct&quot;)}
                  &lt;/Text&gt;
                )}
              &lt;/View&gt;
            );
          }}
          onRefresh={() =&gt; onRefresh()}
          refreshing={isFetching}
          keyExtractor={(item) =&gt; item.image}
          numColumns={2}
          data={filtredList}
          renderItem={({ item }) =&gt; {
            return (
              &lt;TouchableWithoutFeedback
                onPress={() =&gt; {
                  navigation.push(&quot;ProductDetails&quot;, {
                    selectedProduct: item,
                  });
                }}
              &gt;
                &lt;View
                  style={{
                    backgroundColor: &quot;white&quot;,
                    alignItems: &quot;center&quot;,
                    padding: 3,
                    elevation: 4,
                    borderRadius: 10,
                    margin: 6,
                  }}
                &gt;
                  &lt;View&gt;
                    &lt;Image
                      source={{ uri: item.image }}
                      style={{
                        height: productCardWidth,
                        width: productCardWidth,
                        borderRadius: 10,
                        marginBottom: 5,
                        zIndex: 1,
                      }}
                    /&gt;

                    &lt;View
                      style={{
                        alignItems: &quot;center&quot;,
                        justifyContent: &quot;center&quot;,
                        height: productCardWidth,
                        width: productCardWidth,
                        position: &quot;absolute&quot;,
                        backgroundColor: Colors.lightGray,
                        borderRadius: 10,
                        marginBottom: 5,
                        zIndex: 0,
                      }}
                    &gt;
                      &lt;ActivityIndicator
                        color={Colors.accentColor}
                        size={&quot;small&quot;}
                        style={{
                          top: 10,
                          right: 10,
                          position: &quot;absolute&quot;,
                        }}
                      /&gt;
                      &lt;FontAwesome5
                        name={&quot;image&quot;}
                        size={26}
                        color={&quot;black&quot;}
                        style={
                          {
                            // position: &quot;absolute&quot;,
                          }
                        }
                      /&gt;
                    &lt;/View&gt;
                  &lt;/View&gt;
                  &lt;Text
                    style={{
                      color: Colors.dark,
                      fontWeight: &quot;bold&quot;,
                      fontSize: 16,
                    }}
                  &gt;
                    {item.title.length &gt; 12
                      ? item.title.slice(0, 12) + &quot;...&quot;
                      : item.title}
                  &lt;/Text&gt;
                  &lt;Text
                    style={{
                      fontWeight: &quot;bold&quot;,
                    }}
                  &gt;
                    {item.price} {item.currency}
                  &lt;/Text&gt;
                &lt;/View&gt;
              &lt;/TouchableWithoutFeedback&gt;
            );
          }}
        /&gt;
