<p><strong>this is root.js</strong></p>
<pre><code>import React, { useState, useEffect } from &quot;react&quot;;
import { NavigationContainer } from &quot;@react-navigation/native&quot;;
import { createNativeStackNavigator } from &quot;@react-navigation/native-stack&quot;;
import AuthStack from &quot;./AuthStack&quot;;
import HomeStack from &quot;./HomeStack&quot;;
import Firebase from &quot;../config/firebase&quot;;
import { Text } from &quot;react-native&quot;;
import { setCurrentUser } from &quot;../staticValues/CurrentUser&quot;;
import Splach from &quot;../components/Splach&quot;;

export default function Root() {
  const Stack = createNativeStackNavigator();
  // Set an initializing state whilst Firebase connects
  const [initializing, setInitializing] = useState(true);
  const [user, setUser] = useState();

  // Handle user state changes
  function onAuthStateChanged(curentUser) {
    setCurrentUser(curentUser);
    setUser(curentUser);
    if (initializing) setInitializing(false);
  }

  useEffect(() =&gt; {
    const subscriber = Firebase.auth().onAuthStateChanged(onAuthStateChanged);
    return subscriber; // unsubscribe on unmount
  }, []);
  if (initializing) {
    return &lt;Splach /&gt;;
  } else {
    return (
      &lt;NavigationContainer&gt;
        {user ? (
          &lt;Stack.Navigator
            screenOptions={{
              headerShown: false,
            }}
          &gt;
            &lt;Stack.Screen name=&quot;HomeStack&quot; component={HomeStack} /&gt;
          &lt;/Stack.Navigator&gt;
        ) : (
          &lt;Stack.Navigator
            screenOptions={{
              headerShown: false,
            }}
          &gt;
            &lt;Stack.Screen name=&quot;AuthStack&quot; component={AuthStack} /&gt;
          &lt;/Stack.Navigator&gt;
        )}
      &lt;/NavigationContainer&gt;
    );
  }
}

</code></pre>,"<p>Okay so the issue in your code is that you are currently in a different Tab/Stack ie the history stack but the file you are accessing is in the ProductStack, so when you call the navigator it does what it is supposed to do, ie. navigate to the ProductDetails page, but since it's declared in the ProductStack, the updation happens there itself.</p>

