        newElement.innerHTML = `&lt;a class=&quot;menu__link&quot; id=&quot;menu__${section.id}&quot; href=&quot;#${section.id}&quot;&gt; ${section.dataset.nav}&lt;/a&gt;`;
        fragment.appendChild(newElement);
