<p>Our application is pretty basic. The server is supposed to receive a handful of text lines (data), merge and parse them, and once the connection is closed (data sending is over) it sends the data to the api.</p>
<pre><code>var net = require('net');
var fs = require('fs');
const axios = require('axios')

const server = new net.Server();
server.listen(PORT, IP);

server.on(&quot;connection&quot;, client =&gt; {
    client.write(&quot;Hello\n&quot;);
    console.log('connected');

    let received = &quot;&quot;;
    client.on(&quot;data&quot;, data =&gt; {
       received += data
       console.log(&quot;Partial data is: &quot; + data);
    });

    client.on(&quot;close&quot;, () =&gt; {
        received = received.toString('utf8');
        fs.appendFile('log.txt', received, function (err) {});

        received = received.replace(/(?:\r\n|\r|\n)/g, &quot;||&quot;);
        axios.post(APIADDRESS, {data: received});
        console.log('Full data is: '+ {data: received});
    });
});
</code></pre>
<p>To send the data I'm simply running a <code>netcat</code> or <code>nc</code> using the <code>netcat ipaddress port</code>, that's not a problem. It's connecting fine, status message is received.</p>
