    )
})

return (
    &lt;View&gt;
        {markers}
    &lt;/View&gt;
)
}

export default SupermarketList

</code></pre>

<p>In my mapView.js I use the marker function like this:</p>
<pre class="lang-js prettyprint-override"><code>&lt;MapView style={styles.map} 
       initialRegion={{
        latitude: 51.926517,
        longitude: 4.462456,
        latitudeDelta: 0.0922,
        longitudeDelta: 0.0421,
      }}
    &gt;
        &lt;Marker coordinate={pin}
        draggable={true}
        onDragStart={(e) =&gt;{
          console.log(&quot;Drag start&quot;, e.nativeEvent.coordinates)
