  const jwt = await new jose.SignJWT({
    &quot;urn:example:claim&quot;: true,
  })
    .setProtectedHeader({ alg: &quot;HS256&quot; })
    .setExpirationTime(&quot;1h&quot;)
    .sign(secretKey);

  return jwt;
} 

// Expose static content
