// This works but is this okay?
signJWT().then((jwt) =&gt; app.use(&quot;/login&quot;, routes({ jwt: jwt })));

app.listen(81); 
console.log(&quot;Listening on port 81&quot;); 
</code></pre>
<p><strong>The callback in question:</strong></p>
<p>Should <code>app.use()</code> even be in callbacks?</p>
