calling function in difference ways<p>what is difference between</p>
<pre><code>//debounce.ts
function debounce(func: Function, timeout = 3000) {
  let timer: any

  return () =&gt; {
    clearTimeout(timer)
    timer = setTimeout(() =&gt; {
      func.apply(func)
    }, timeout)
  }
}

function callDebounce(apiCallFunc: Function) {
  const yui = debounce(() =&gt; {
    apiCallFunc()
  })

  return yui()
}

export default callDebounce
</code></pre>
<p>and</p>
<pre><code>//debounce.ts
import apiCallFunc from &quot;./controller&quot;

