      Get.offAll(() =&gt; const HomeScreen());
      userModel?.bindStream(listenToUser());
      print(userModel);
    }
  }

  // registering the user
  void registerUser(String username, String email, String password) async {
    try {
      if (username.isNotEmpty &amp;&amp; email.isNotEmpty &amp;&amp; password.isNotEmpty) {
        // save our user to our auth and firebase firestore
        UserCredential cred = await firebaseAuth.createUserWithEmailAndPassword(
          email: email,
          password: password,
        );
        model.User user = model.User(
            name: username, email: email, uid: cred.user!.uid, cart: []);
        await firestore
            .collection('users')
            .doc(cred.user!.uid)
            .set(user.toJson());
      } else {
        Get.snackbar(
          'Error Creating Account',
          'Please enter all the fields',
        );
      }
    } catch (e) {
      Get.snackbar(
        'Error Creating Account',
        e.toString(),
      );
    }
  }

  void loginUser(String email, String password) async {
    try {
      if (email.isNotEmpty &amp;&amp; password.isNotEmpty) {
        await firebaseAuth.signInWithEmailAndPassword(
            email: email, password: password);
        print('log success');
      } else {
        Get.snackbar(
          'Error Logging in',
          'Please enter all the fields',
        );
      }
    } catch (e) {
      Get.snackbar(
        'Error Logging in',
        e.toString(),
      );
    }
  }

  updateUserData(Map&lt;String, dynamic&gt; data) {
    print(&quot;UPDATED&quot;);
    firestore.collection('users').doc(_user.value?.uid).update(data);
  }

  Stream&lt;model.User&gt; listenToUser() =&gt; firestore
      .collection('users')
      .doc(_user.value?.uid)
      .snapshots()
      .map((snapshot) =&gt; model.User.fromSnap(snapshot));
}
